import React from 'react';
import { useApp } from '../context/AppContext';

const ROLE_META = {
  manager: { label: 'Menejer',    emoji: '👔', color: 'text-purple-400', border: 'border-purple-500/30', bg: 'bg-purple-500/10' },
  waiter:  { label: 'Ofitsiant',  emoji: '🧑‍🍳', color: 'text-blue-400',   border: 'border-blue-500/30',   bg: 'bg-blue-500/10' },
  chef:    { label: 'Oshpaz',     emoji: '👨‍🍳', color: 'text-amber-400',  border: 'border-amber-500/30',  bg: 'bg-amber-500/10' },
  cashier: { label: 'Kassir',     emoji: '💰', color: 'text-emerald-400', border: 'border-emerald-500/30', bg: 'bg-emerald-500/10' },
};

const PERM_LABELS = {
  seatCustomers: 'Mijoz o\'tqazish',
  takeOrders:    'Buyurtma qabul qilish',
  manageKitchen: 'Oshxonani boshqarish',
  accessBilling: 'Hisob-kitob',
  manageStaff:   'Xodimlarni boshqarish',
};

export default function StaffView() {
  const { staff } = useApp();

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {Object.entries(ROLE_META).map(([role, meta]) => {
          const count = staff.filter((s) => s.role === role).length;
          return (
            <div key={role} className={`card border ${meta.border} p-4 text-center`}>
              <p className="text-3xl mb-2">{meta.emoji}</p>
              <p className={`text-2xl font-bold ${meta.color}`}>{count}</p>
              <p className="text-gray-500 text-xs mt-1">{meta.label}</p>
            </div>
          );
        })}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
        {staff.map((member) => {
          const meta = ROLE_META[member.role] || ROLE_META.waiter;
          const permCount = Object.values(member.permissions || {}).filter(Boolean).length;
          const totalPerms = Object.keys(PERM_LABELS).length;

          return (
            <div key={member.id} className={`card border ${meta.border} overflow-hidden`}>
              {/* Header */}
              <div className={`${meta.bg} px-5 py-4 flex items-center justify-between`}>
                <div className="flex items-center gap-3">
                  <div className={`w-10 h-10 rounded-xl border ${meta.border} flex items-center justify-center text-xl`}>
                    {meta.emoji}
                  </div>
                  <div>
                    <p className="text-white font-bold">{member.name}</p>
                    <p className={`text-xs ${meta.color}`}>{meta.label}</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className={`text-lg font-bold ${meta.color}`}>{permCount}/{totalPerms}</p>
                  <p className="text-gray-600 text-[10px]">ruxsat</p>
                </div>
              </div>

              {/* Permissions */}
              <div className="px-5 py-4 space-y-2">
                {Object.entries(PERM_LABELS).map(([perm, label]) => {
                  const allowed = member.permissions?.[perm];
                  return (
                    <div key={perm} className="flex items-center gap-2.5">
                      <div className={`w-5 h-5 rounded-md flex items-center justify-center text-xs ${
                        allowed ? `${meta.bg} ${meta.color}` : 'bg-white/[0.03] text-gray-700'
                      }`}>
                        {allowed ? '✓' : '×'}
                      </div>
                      <span className={`text-sm ${allowed ? 'text-gray-200' : 'text-gray-600'}`}>{label}</span>
                    </div>
                  );
                })}
              </div>

              {/* ID footer */}
              <div className="px-5 py-3 border-t border-white/[0.04]">
                <p className="text-[10px] text-gray-700 font-mono">{member.id}</p>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
